UPDATE public.exercise_questions SET question_text = 'Uma equipe quer compreender como professores interpretam uma política curricular. Pretende comparar entrevistas, documentos da política e registros de observação, distinguindo relatos, contexto e interpretação. Qual procedimento é mais coerente com uma abordagem qualitativa rigorosa?', feedback_hint = 'Considere a pergunta de pesquisa, a adequação das fontes e a distinção entre dado e interpretação.' WHERE id = '40ca79bf-4ba0-4d63-8956-9a4a12726944';
UPDATE public.exercise_options SET content = CASE position WHEN 1 THEN 'Somar a frequência de palavras nas entrevistas e tratar esse número como explicação suficiente dos sentidos atribuídos pelos professores.' WHEN 2 THEN 'Triangular as fontes quando pertinente, contextualizar os relatos e explicitar como os dados sustentam a interpretação, reconhecendo seus limites.' WHEN 3 THEN 'Selecionar apenas os depoimentos que confirmem a hipótese inicial e descartar divergências como respostas inválidas.' WHEN 4 THEN 'Generalizar as conclusões para todos os professores a partir de uma entrevista considerada representativa, sem justificar a transferência.' END, feedback_incorrect = CASE position WHEN 1 THEN 'A contagem pode ser útil em certas análises, mas, isoladamente, não explica os sentidos e processos que a pergunta qualitativa busca compreender.' WHEN 2 THEN 'Correto. O procedimento articula pergunta, fontes e interpretação, preservando a rastreabilidade dos argumentos e os limites do estudo.' WHEN 3 THEN 'Descartar dados divergentes introduz viés de confirmação e impede investigar perspectivas diferentes presentes no campo.' WHEN 4 THEN 'Uma experiência local não autoriza generalização automática; é necessário explicitar contexto, condições e limites de transferência.' END WHERE question_id = '40ca79bf-4ba0-4d63-8956-9a4a12726944';
UPDATE public.exercise_options SET is_correct = (position = 2) WHERE question_id = '40ca79bf-4ba0-4d63-8956-9a4a12726944';
UPDATE public.exercise_questions SET question_text = 'Uma rede municipal compara resultados de matemática de duas escolas e observa média maior na Escola A. Antes de atribuir a diferença à prática docente, qual decisão metodológica é mais defensável?', feedback_hint = 'Diferencie comparação numérica, associação e explicação causal; verifique como as medidas e os grupos foram construídos.' WHERE id = '4d2ce4d8-b682-432f-a7c7-bc468717ef44';
UPDATE public.exercise_options SET content = CASE position WHEN 1 THEN 'Concluir que a Escola A ensina melhor, pois uma média maior demonstra diretamente a causa da diferença.' WHEN 2 THEN 'Examinar população e composição dos grupos, período, instrumento de medida e condições de aplicação, reconhecendo que a diferença não prova causalidade por si só.' WHEN 3 THEN 'Aumentar a amostra sem rever a qualidade da medida ou a forma de seleção dos estudantes, pois tamanho amostral resolve vieses.' WHEN 4 THEN 'Usar apenas a significância estatística para decidir qual escola é melhor, sem avaliar magnitude, incerteza ou relevância educacional.' END, feedback_incorrect = CASE position WHEN 1 THEN 'A diferença observada é descritiva; sem desenho adequado e consideração de variáveis relevantes, não identifica a causa.' WHEN 2 THEN 'Correto. A interpretação quantitativa exige avaliar medida, grupos, condições e limites antes de inferir relações causais.' WHEN 3 THEN 'Uma amostra maior não corrige automaticamente medida inadequada ou seleção enviesada.' WHEN 4 THEN 'Significância estatística não substitui análise de magnitude, contexto, incerteza e importância prática.' END WHERE question_id = '4d2ce4d8-b682-432f-a7c7-bc468717ef44';
UPDATE public.exercise_options SET is_correct = (position = 2) WHERE question_id = '4d2ce4d8-b682-432f-a7c7-bc468717ef44';
